SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='67bf4cac-41ba-5646-ac47-1a2f92774cd0'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('8f2d2386-621d-586c-b40f-3a6ed0bb7b13','b423cf30-d20b-50a3-bfe1-f82dd71130a7')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='67bf4cac-41ba-5646-ac47-1a2f92774cd0'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='67bf4cac-41ba-5646-ac47-1a2f92774cd0'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('8f2d2386-621d-586c-b40f-3a6ed0bb7b13','b423cf30-d20b-50a3-bfe1-f82dd71130a7')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='67bf4cac-41ba-5646-ac47-1a2f92774cd0'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
