  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-11-missing-evidence-status' AND q.fingerprint='0046efc1a76db32c219da6369c6fe7c35e24669c3aefa15d06d69c1ba798afb1'
