  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-11-missing-evidence-status","status":"ok","value":{"customerProfileId":"67bf4cac-41ba-5646-ac47-1a2f92774cd0","userId":"25aee674-3524-5f7b-80c5-0ab0873acaf2","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"8f2d2386-621d-586c-b40f-3a6ed0bb7b13","semanticKey":"customer-controls-customer-11-missing-evidence-status","fingerprint":"0046efc1a76db32c219da6369c6fe7c35e24669c3aefa15d06d69c1ba798afb1","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='72d5187f-6376-5a53-a6e5-1e44f64e2605' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='46698b8f-ea18-5239-94ad-ef903a055f62' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"67bf4cac-41ba-5646-ac47-1a2f92774cd0"},"prior":null,"committed":{"id":"67bf4cac-41ba-5646-ac47-1a2f92774cd0","userId":"25aee674-3524-5f7b-80c5-0ab0873acaf2","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='67bf4cac-41ba-5646-ac47-1a2f92774cd0' AND c.user_id='25aee674-3524-5f7b-80c5-0ab0873acaf2' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
