   AND ((o.id='c3a69f4e-44c3-5b71-b877-90733cd242b8' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"67bf4cac-41ba-5646-ac47-1a2f92774cd0","userId":"25aee674-3524-5f7b-80c5-0ab0873acaf2","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='cb49a9c0-9fdc-5009-ba64-79154f2b62b2' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"25aee674-3524-5f7b-80c5-0ab0873acaf2","track":"customer","customerProfileId":"67bf4cac-41ba-5646-ac47-1a2f92774cd0","sourceCreationRevision":"0","sourceCreationReceipt":"8f2d2386-621d-586c-b40f-3a6ed0bb7b13","semanticKey":"customer_buyer_profile/67bf4cac-41ba-5646-ac47-1a2f92774cd0/default-free-enrollment/v1"}'::jsonb)))=2));
